import {VERSION,STORAGE_KEY,STEPS,DATA,TRANSFER_DATA,backtest,PRACTICE,ASSESSMENTS,check,grade,freshState,restoreState,invalidate,labEvidence} from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),storageOK=true,page='start';try{state=restoreState(localStorage.getItem(STORAGE_KEY));}catch{storageOK=false;}
const value=id=>state.fields[id]||'',fmt=n=>n===null?"未定義":Number(n).toFixed(3),field=(id,label,area=false,defaultValue='')=>`<label class="field" for="${id}">${label}</label>${area?`<textarea id="${id}" data-save>${esc(state.fields[id]??defaultValue)}</textarea>`:`<input id="${id}" data-save type="number" step="any" value="${esc(state.fields[id]??defaultValue)}">`}`,box=(id,label)=>`<label class="option"><input id="${id}" type="checkbox" data-save ${value(id)==='yes'?'checked':''}><span>${label}</span></label>`;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?"已儲存在此裝置":"無法儲存 · 離開前請匯出";nav();}
function nav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#progress-label').textContent=`${n}／8步已完成`;$('#progress-percent').textContent=Math.round(n/8*100)+'%';$('#progress').value=n;$('#navigation').innerHTML=STEPS.map(([id,t,m],i)=>`<a href="#${id}" ${id===page?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':i+1}</span><span>${t}<small>${m} 分鐘${state.done[id]?" · 已完成":''}</small></span></a>`).join('');}
function feedback(id,text,error=false){const el=$('#'+id);el.textContent=text;el.className='feedback'+(error?' error':'');el.tabIndex=-1;el.focus();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const table=(data=DATA)=>`<div class="table-wrap"><table><caption>原創合成${data===DATA?'development':'transfer'}價格，單位英鎊／單位。日期標示依序的教學觀察，週末刻意視為假設交易日。</caption><thead><tr><th>日期</th><th>開盤價（£）</th><th>收盤價（£）</th></tr></thead><tbody>${data.map(r=>`<tr><th scope="row">${r.date}</th><td>${r.open}</td><td>${r.close}</td></tr>`).join('')}</tbody></table></div><p><a href="prices.csv" download>開發資料 CSV</a> · <a href="transfer-prices.csv" download>遷移練習 CSV</a> · <a href="data-dictionary.md">資料字典</a></p>`;
const header=(title,lead)=>`<div class="eyebrow">第08章 · ${STEPS.find(s=>s[0]===page)?.[2]} 分鐘utes</div><h1>${title}</h1><p class="lead">${lead}</p>`;
function start(){return header("逐筆追溯<br><em>每次交易。</em>","可信結果需要清楚時序、每筆費用與公平比較。先實作一項固定規則，再解讀績效。")+`<div class="pill-row"><span class="pill">180分鐘核心</span><span class="pill">不需安裝</span><span class="pill">Python選修另加30分鐘</span></div><section class="panel"><h2>獨立學習準備</h2><p>準備計算機與紙。先備：百分比、複利資產與三值平均。暖身：(100+101+102)/3=101；1000×.999=999。不需程式能力。瀏覽器與完整紙本路線提供示範、提示、遷移檢核、回饋與修訂。</p><p>時間：準備10；時序25；部位25；成本30；基準25；實驗35；獨立遷移20；證據卡10=180分鐘。估計待學員測試；沒有倒數限制。</p><p><a href="guide.html">完整文字與紙本路線</a>。各章進度獨立。匯出下載答案、每次檢核嘗試、試驗與修訂；不是匯入／同步。勿輸入個人帳戶資料。</p>${box('setup',"我找到資料、計算機、完整文字路線、匯出及隱私與重設。")}<button data-action="setup">確認準備並繼續</button><div id="feedback-start" class="feedback" role="status"></div></section><section class="panel"><h2>執行前先固定</h2><p>規則：收盤價嚴格高於移動3筆收盤平均→權重1；否則0。收盤t後訊號；開盤t+1執行；賺取開盤t+1→開盤t+2。起始£1000，交易名目金額成本10bps，現金0%。無槓桿、放空、配息、違約、稅或額外滑價。計首次進場與最後出場。不最佳化規則，保留每次執行與成本敏感度。</p><p>成果：追溯時序、重現部位、計算淨資產與最後平倉、對齊買入持有區間，並解釋合成執行為何不能驗證獲利能力。</p>${table()}</section>`;}
function practice(step){const l=LESSONS[step];return header(l.title,l.objective)+l.body+table()+`<section class="panel"><h2>嘗試、檢查、解釋、修訂</h2><p>可用計算機。只填數字，不加%符號。四捨五入至小數兩位或保留更多位。選擇題輸入指定數字。</p>${PRACTICE[step].map((q,i)=>`<div class="practice-item">${field(q.id,q.title)}<div class="actions"><button data-action="practice" data-id="${q.id}">檢查任務 ${i+1}</button><details><summary>提示</summary><p>${q.hint}</p></details></div><div id="feedback-${q.id}" class="feedback" role="status">${state.checked[q.id]?"正確。"+q.hint:''}</div></div>`).join('')}<h3>解釋與修訂</h3><p>${l.reflection}</p>${field(step+'Reflection',"我的解釋、核對或修正",true)}${box(step+'Criteria',l.criteria)}<p class="mini">自評檢查推理；應用程式只檢查數值答案及至少30字。文字品質不自動評分。</p><button data-action="save-step">儲存本節</button><div id="feedback-step" class="feedback" role="status">${state.done[step]?"本節證據已儲存。":''}</div></section>`;}
function runResult(run){const x=run.result;return `<h3>固定3筆收盤規則，成本${run.cost}bps</h3><div class="result-grid"><p>策略最終£${fmt(x.finalWealth)}<br>淨變動${fmt(x.totalReturn*100)}%</p><p>基準最終£${fmt(x.benchmarkFinal)}<br>淨變動${fmt(x.benchmarkReturn*100)}%</p></div><p>最後出場費：策略£${fmt(x.finalExitCost)}，基準£${fmt(x.benchmarkExitCost)}。下方最後一列尚未扣平倉費。基準與策略可交易開盤點：1 月 5 日→Jan17。</p><div class="table-wrap run-list"><table><caption>完整執行紀錄。進場先扣成本再計區間報酬率。資產單位英鎊；顯示數字只為閱讀而四捨五入。</caption><thead><tr><th>訊號收盤</th><th>平均</th><th>執行開盤</th><th>評價開盤</th><th>權重</th><th>換手比例</th><th>標的毛報酬率%</th><th>起始£</th><th>期末£</th><th>基準£</th></tr></thead><tbody>${x.rows.map(r=>`<tr><th scope="row">${r.signalDate}</th><td>${fmt(r.average)}</td><td>${r.entryDate}</td><td>${r.exitDate}</td><td>${r.position}</td><td>${r.turnover}</td><td>${fmt(r.grossReturn*100)}</td><td>${fmt(r.startWealth)}</td><td>${fmt(r.endWealth)}</td><td>${fmt(r.benchmarkEnd)}</td></tr>`).join('')}</tbody></table></div>`;}
function lab(){const r=state.runs.at(-1);return header("規則保持固定。","只改成本假設，手算第一區間並保留兩次試驗。較差結果也是有用證據。")+`<p>這是預定規則的敏感度分析，不是參數搜尋。開發資料已公開。最後卡片與第9–10章須揭露已接觸資料及全部試驗。原創價格試驗不是市場樣本外驗證。</p><section class="panel"><h2>先預測再計算</h2>${field('prediction',"預測價格與部位固定時，提高成本會如何影響最終資產，並說明原因（20字以上）。",true)}${field('cost',"每交易名目金額成本，基點（0–100）",false,'10')}<button data-action="run">執行固定規則</button><div id="feedback-run" class="feedback" role="status"></div>${r?runResult(r):"<p>此處顯示完整執行紀錄。</p>"}</section><section class="panel"><h2>手算並修訂</h2><p>首個權重1，進場103，下次開盤100，起始£1000。核對1000×(1−cost/10000)×100/103。再只改成本（試10→30bps）；所有價格、時序與視窗不變。不可看結果後挑較好看的費率。</p>${field('hand',"最新第一區間末資產，尚未後續出場（£）")}<button data-action="hand">檢查我的手算</button><div id="feedback-hand" class="feedback" role="status">${value('handVerified')==='yes'?"最新第一區間已核對。":''}</div>${field('labReflection',"比較不同成本下策略與基準淨資產，修訂預測並指出執行限制（50字以上）。",true)}${box('labCriteria',"我固定規則／資料、納入最後出場、對齊可交易開盤點，且不宣稱獲利能力。")}<details><summary>回饋條件</summary><p>在不變0/1部位與非負費率下，較高成本不能提高最終資產。兩者都付進出費，但換手可能不同。逐筆對照紀錄；現金區間仍可能支付出場費。省略滑價或現實流動性可能使結果樂觀。短小合成序列不提供市場優勢證據。</p></details><button data-action="save-lab">儲存實驗證據</button><button data-action="csv" class="secondary">匯出全部執行紀錄CSV</button><div id="feedback-lab" class="feedback" role="status"></div></section><section class="panel"><h2>保留全部試驗</h2><ol>${state.runs.map(r=>`<li>${esc(r.time)};cost${r.cost}bps；策略£${fmt(r.result.finalWealth)}，基準£${fmt(r.result.benchmarkFinal)}；預測：${esc(r.prediction)}</li>`).join('')||"<li>尚無執行。</li>"}</ol></section>`;}
function assessment(){const a=state.attempts.at(-1);return header("使用新案例。","獨立遷移 · 先作答八題再檢查。回應回饋，需要時修訂再交。")+`<section class="panel"><p>不倒數，可用計算機與紙。先獨立作答再看回饋。通過：至少7/8，且回饋標示的全部關鍵模型或時序慣例正確。這是形成性自主學習，不是保密考試或證照。</p>${table(TRANSFER_DATA)}${ASSESSMENTS.map(q=>field('quiz-'+q.id,q.title)).join('')}<button data-action="grade">檢查獨立嘗試</button><div id="feedback-assessment" class="feedback" role="status">${a?`${a.score}／8，為上次繳交結果。${a.passed?"數值與關鍵條件已符合。":"請修訂再繳。"} ${value('quizDirty')==='yes'?"答案或回應已變更，請重交當前答案。":''}`:''}</div><details><summary>過往嘗試紀錄（${state.attempts.length})</summary><ol>${state.attempts.map(a=>`<li>${esc(a.time)}: ${a.score}/8; ${a.passed?"符合條件":"重查"}${a.revision?" · 回應已儲存":''}</li>`).join('')}</ol></details><h2>回應回饋</h2>${field('revision',"說明一項具體修正或核對及原因（至少30字）。",true)}<button data-action="revision">儲存回饋回應</button><div id="feedback-revision" class="feedback" role="status">${state.done.assessment?"獨立證據與回應已儲存。":''}</div></section>`;}
function finish(){return header("儲存你的證據。","最後卡片記錄方法、可重現算術、時序或模型假設，以及限制。")+`<section class="panel">${field('cardMethod',"方法與假設（30字以上）",true)}${field('cardCheck',"已核對數值、單位與可重現計算（30字以上）",true)}${field('cardLimit',"重要限制與下一步所需證據（30字以上）",true)}${box('cardCriteria',"我依規準檢查卡片，並修正一項缺乏證據的主張。")}<details><summary>自評規準</summary><p>方法：列輸入、假設與時序。計算：以單位和完整精度手算追溯，再四捨五入。限制：區分假設機制與市場證據。回應：指出具體修訂。文字自行檢核，儲存不證明實質熟練。</p></details><button data-action="card">儲存證據卡</button><div id="feedback-finish" class="feedback" role="status"></div><ul>${STEPS.map(([id,t])=>`<li>${state.done[id]?"已完成":"待完成"}: ${t}</li>`).join('')}</ul><button data-action="export">匯出完整本章紀錄</button></section><section class="panel"><h2>來源與進一步鞏固</h2><ul>${SOURCES.map(([t,u])=>`<li><a href="${u}">${t}</a></li>`).join('')}</ul><p>原創合成教學資料。主要來源查核於31 October 2026。學習時間與文字規準須真人驗證；完整螢幕閱讀器測試與試學仍待進行。</p><p><a href="../python/?chapter=8#ch8-timing">選修Python鞏固（另加30分鐘）</a>：兩個標準函式庫程式、分開進度；設定時間另計，超出30小時非程式核心。</p><p><a href="../chapter-09/">繼續第9章</a></p></section>`;}
function render(focus=true){const next=location.hash.slice(1)||'start';if(next==='lesson'&&$('#lesson').children.length){$('#lesson').focus();return;}page=next;if(!STEPS.some(s=>s[0]===page))page='start';const i=STEPS.findIndex(s=>s[0]===page);$('#lesson').innerHTML=(LESSONS[page]?practice(page):({start,lab,assessment,finish}[page])())+`<div class="bottom-nav">${i?`<a href="#${STEPS[i-1][0]}">← 上一步</a>`:"<a href=\"../chapter-07/\">← 第7章</a>"}${i<7?`<a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]}</a>`:"<a href=\"#start\">返回總覽 ↑</a>"}</div>`;nav();if(focus)$('#lesson').focus();}
document.addEventListener('input',e=>{if(!e.target.matches('[data-save]'))return;const id=e.target.id;state.fields[id]=e.target.type==='checkbox'?(e.target.checked?'yes':''):e.target.value;invalidate(state,id);persist();});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#lesson').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='export'){download('qf-chapter-08-record.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2));$('#announcement').textContent="第8章紀錄已匯出。";}
if(action==='setup'){if(value('setup')!=='yes')return feedback('feedback-start',"請先確認準備清單。",true);state.done.start=true;persist();location.hash='timing';}
if(action==='practice'){const q=Object.values(PRACTICE).flat().find(q=>q.id===e.target.dataset.id),ok=check(q,value(q.id));state.checked[q.id]=ok;state.practiceAttempts.push({id:q.id,raw:value(q.id),correct:ok,time:new Date().toISOString()});delete state.done[page];persist();feedback('feedback-'+q.id,ok?"正確。"+q.hint:"重查。"+q.hint+"請依指定單位修訂並重查。",!ok);}
if(action==='save-step'){if(!PRACTICE[page].every(q=>state.checked[q.id]&&check(q,value(q.id)))||value(page+'Reflection').trim().length<30||value(page+'Criteria')!=='yes')return feedback('feedback-step',"正確核對兩項任務、寫具體說明（30字以上）並確認自評。",true);state.done[page]=true;persist();feedback('feedback-step',"本節證據已儲存；文字依指定條件自行檢核。");}
if(action==='run'){if(value('prediction').trim().length<20)return feedback('feedback-run',"執行前先寫至少20字預測與理由。",true);try{if(String(state.fields.cost??10).trim()==='')throw Error("請明確填成本，若為零則填0。空白不代表零。");const cost=Number(state.fields.cost??10),result=backtest(DATA,{costBps:cost});state.runs.push({cost,result,prediction:value('prediction'),time:new Date().toISOString()});state.fields.hand='';state.fields.handVerified='';delete state.done.lab;persist();render(false);feedback('feedback-run',"已記錄執行與最後出場。先驗證第一區間，再只改成本。");}catch(err){feedback('feedback-run',err.message,true);}}
if(action==='hand'){const r=state.runs.at(-1),ok=r&&check({answer:r.result.rows[0].endWealth,tolerance:.011},value('hand'));state.fields.handVerified=ok?'yes':'';delete state.done.lab;persist();feedback('feedback-hand',ok?"正確：最新第一區間已驗證。":"最新執行使用1000×(1−cost/10000)×100/103。修訂後重查。",!ok);}
if(action==='save-lab'){if(!labEvidence(state))return feedback('feedback-lab',"當前輸入與預測須對應最新執行；比較兩種成本、驗證最新第一區間，並寫50字以上反思與自評。",true);state.done.lab=true;persist();feedback('feedback-lab',"固定規則敏感度證據已儲存。");}
if(action==='csv'){if(!state.runs.length)return feedback('feedback-lab',"請先執行固定規則。",true);download('qf-chapter-08-all-ledgers.csv','run,cost_bps,signal_date,entry_date,exit_date,position,turnover,gross_return_decimal,start_wealth_gbp,end_wealth_gbp,benchmark_end_gbp,final_exit_cost_gbp,benchmark_exit_cost_gbp\n'+state.runs.flatMap((r,i)=>r.result.rows.map(p=>[i+1,r.cost,p.signalDate,p.entryDate,p.exitDate,p.position,p.turnover,p.grossReturn,p.startWealth,p.endWealth,p.benchmarkEnd,r.result.finalExitCost,r.result.benchmarkExitCost].join(','))).join('\n'),'text/csv');}
if(action==='grade'){const answers=Object.fromEntries(ASSESSMENTS.map(q=>[q.id,value('quiz-'+q.id)]));if(ASSESSMENTS.some(q=>answers[q.id].trim()===''))return feedback('feedback-assessment',"先答完八題再檢查；不限時間。",true);const result=grade(answers);state.attempts.push({...result,answers,time:new Date().toISOString()});state.fields.quizDirty='';state.fields.revision='';delete state.done.assessment;persist();feedback('feedback-assessment',`${result.score}/8. ${result.passed?"條件已符合，現在記錄回饋回應。":"修訂再交；全部關鍵慣例必須正確。"} `+ASSESSMENTS.map(q=>`${q.id}: ${check(q,answers[q.id])?'Correct':'Revisit'} — ${q.hint}`).join(' '),!result.passed);}
if(action==='revision'){const a=state.attempts.at(-1);if(!a||!ASSESSMENTS.every(q=>a.answers[q.id]===value('quiz-'+q.id)))return feedback('feedback-revision',"請先繳交當前答案，再儲存其回饋回應。",true);if(value('revision').trim().length<30)return feedback('feedback-revision',"說明一項具體修正或驗證（至少30字）。",true);a.revision=value('revision');state.fields.quizDirty='';if(a.passed)state.done.assessment=true;persist();feedback('feedback-revision',a.passed?"回饋回應已儲存，獨立檢核完成。":"回應已儲存；修訂答案再交以符合條件。");}
if(action==='card'){if(!['cardMethod','cardCheck','cardLimit'].every(id=>value(id).trim().length>=30)||value('cardCriteria')!=='yes')return feedback('feedback-finish',"三個欄位各完成30字以上，並確認自評。",true);state.done.finish=true;persist();render(false);feedback('feedback-finish',STEPS.every(([id])=>state.done[id])?"本章完成。請匯出證據與卡片保存。":"證據卡已儲存；依清單補齊缺少的證據。");}
});
$('#chapter-select').addEventListener('change',e=>{location.href=e.target.value==='1'?'../index.html':`../chapter-${e.target.value.padStart(2,'0')}/`;});$('#privacy-button').onclick=()=>$('#privacy-dialog').showModal();$('#close-privacy').onclick=()=>$('#privacy-dialog').close();$('#reset-progress').onclick=()=>{if(!confirm("只刪除第8章瀏覽器進度與執行？其他章及已下載檔案保留。"))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();location.hash='start';render();$('#announcement').textContent='第8章已重設。';};window.addEventListener('hashchange',()=>render());render(false);
